package cli

import (
	"fmt"
	"io"
	"os"
	"sync"
	"time"
)

type refreshProgress struct {
	out     io.Writer
	spinner bool
	mu      sync.Mutex
}

func newRefreshProgress(out io.Writer) *refreshProgress {
	return &refreshProgress{
		out:     out,
		spinner: out == os.Stderr,
	}
}

func (p *refreshProgress) Step(label string) func(error) {
	if p == nil || p.out == nil {
		return func(error) {}
	}
	if p.spinner {
		return p.spinnerStep(label)
	}
	fmt.Fprintf(p.out, "refresh: %s\n", label)
	return func(err error) {
		if err != nil {
			fmt.Fprintf(p.out, "refresh: %s failed\n", label)
			return
		}
		fmt.Fprintf(p.out, "refresh: %s done\n", label)
	}
}

func (p *refreshProgress) Skip(label string) {
	if p == nil || p.out == nil {
		return
	}
	fmt.Fprintf(p.out, "refresh: %s skipped\n", label)
}

func (p *refreshProgress) spinnerStep(label string) func(error) {
	done := make(chan struct{})
	frames := []rune{'|', '/', '-', '\\'}
	go func() {
		ticker := time.NewTicker(120 * time.Millisecond)
		defer ticker.Stop()
		i := 0
		for {
			select {
			case <-done:
				return
			case <-ticker.C:
				p.mu.Lock()
				fmt.Fprintf(p.out, "\r%c %s", frames[i%len(frames)], label)
				p.mu.Unlock()
				i++
			}
		}
	}()
	p.mu.Lock()
	fmt.Fprintf(p.out, "\r%c %s", frames[0], label)
	p.mu.Unlock()
	return func(err error) {
		close(done)
		p.mu.Lock()
		defer p.mu.Unlock()
		if err != nil {
			fmt.Fprintf(p.out, "\r! %s failed\n", label)
			return
		}
		fmt.Fprintf(p.out, "\r✓ %s done\n", label)
	}
}

